options.queryReplacement:
={{ [JSON.stringify({
  workflow: $('Error Trigger').first().json.workflow?.name,
  node: $('Error Trigger').first().json.execution?.lastNodeExecuted,
  error: $('Error Trigger').first().json.execution?.error?.message,
  executionId: $('Error Trigger').first().json.execution?.id,
  timestamp: new Date().toISOString()
})] }}

parameters.jsonBody:
={{ JSON.stringify({
  number: String($env.ESCALATION_PHONE || '').replace(/\D/g, ''),
  text: '⚠️ *System Error*\nWorkflow: ' + ($('Error Trigger').first().json.workflow?.name || 'unknown')
    + '\nNode: ' + ($('Error Trigger').first().json.execution?.lastNodeExecuted || 'unknown')
    + '\nError: ' + ($('Error Trigger').first().json.execution?.error?.message || 'unknown')
}) }}
